/* Part 5: initialize a Network from the header generated by dump_initfile() (e.g. 7seg_net.h).
 *
 * Include the generated header first, then this file:
 *     #include "7seg_net.h"
 *     #include "nn_from_header.h"
 */
#ifndef NN_FROM_HEADER_H
#define NN_FROM_HEADER_H

#include "nn.h"

#ifndef NN_NUM_LAYERS
#error "include the generated network header (e.g. 7seg_net.h) before nn_from_header.h"
#endif

#if defined(NN_ACTIVATION_TANH)
#define NN_HEADER_ACTIVATION NN_TANH
#elif defined(NN_ACTIVATION_RELU)
#define NN_HEADER_ACTIVATION NN_RELU
#else
#define NN_HEADER_ACTIVATION NN_SIGMOID
#endif

/* Allocate the network and copy all weights and biases from the header. Returns 0 on success. */
static inline int nn_init_from_header(Network *net)
{
    if (nn_create(net, NN_NUM_LAYERS, NN_LAYER_SIZES, NN_HEADER_ACTIVATION) != 0)
        return -1;
    for (int l = 0; l < NN_NUM_LAYERS - 1; l++) {
        Layer *layer = &net->layers[l];
        for (int n = 0; n < layer->n_neurons; n++) {
            const float *weights;
            float bias;
            nn_get_neuron(l, n, &weights, &bias);
            for (int i = 0; i < layer->neurons[n].n_inputs; i++)
                layer->neurons[n].weights[i] = weights[i];
            layer->neurons[n].bias = bias;
        }
    }
    return 0;
}

#endif /* NN_FROM_HEADER_H */
